{
  "root_causes": [
    {
      "service": "ts-auth-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'normal' p, count(*) n, round(avg(duration)/1e6,1) ms FROM normal_traces WHERE service_name='ts-auth-service' AND span_name='AuthController.createDefaultUser' UNION ALL SELECT 'abnormal', count(*), round(avg(duration)/1e6,1) FROM abnormal_traces WHERE service_name='ts-auth-service' AND span_name='AuthController.createDefaultUser'",
          "claim": "AuthController.createDefaultUser self-time rises from about 74 ms to about 127 ms, with the same call count pattern."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abnormal' p, s.span_name, count(*) n, round(avg(s.duration)/1e6,1) child_ms FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-auth-service' AND c.span_name='AuthController.createDefaultUser' GROUP BY ALL UNION ALL SELECT 'normal', s.span_name, count(*), round(avg(s.duration)/1e6,1) FROM normal_traces s JOIN normal_traces c ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-auth-service' AND c.span_name='AuthController.createDefaultUser' GROUP BY ALL",
          "claim": "Database child UserRepository.save stays around 3 ms in both periods, so the extra time is in the method itself."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'normal' p, metric, round(avg(value),3) v FROM normal_metrics_sum WHERE service_name='ts-auth-service' AND metric='container.cpu.usage' GROUP BY ALL UNION ALL SELECT 'abnormal', metric, round(avg(value),3) FROM abnormal_metrics_sum WHERE service_name='ts-auth-service' AND metric='container.cpu.usage' GROUP BY ALL",
          "claim": "Auth container CPU usage is unchanged from normal, so the slowdown is not resource saturation."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-auth-service",
      "to": "ts-user-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'normal' p, avg(c.duration)/1e6 caller_ms, avg(s.duration)/1e6 callee_ms, count(*) n FROM normal_traces s JOIN normal_traces c ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-user-service' AND c.span_name='POST' AND s.service_name='ts-auth-service' UNION ALL SELECT 'abnormal', avg(c.duration)/1e6, avg(s.duration)/1e6, count(*) FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-user-service' AND c.span_name='POST' AND s.service_name='ts-auth-service'",
          "claim": "ts-user-service's outgoing POST to ts-auth-service rises from about 76 ms to 165 ms, matching the auth server span slowdown."
        }
      ]
    },
    {
      "from": "ts-user-service",
      "to": "ts-admin-user-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'normal' p, avg(c.duration)/1e6 caller_ms, avg(s.duration)/1e6 callee_ms, count(*) n FROM normal_traces s JOIN normal_traces c ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-admin-user-service' AND c.span_name='POST' AND s.service_name='ts-user-service' UNION ALL SELECT 'abnormal', avg(c.duration)/1e6, avg(s.duration)/1e6, count(*) FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-admin-user-service' AND c.span_name='POST' AND s.service_name='ts-user-service'",
          "claim": "ts-admin-user-service's POST to ts-user-service register endpoint rises from about 83 ms to 163 ms."
        }
      ]
    },
    {
      "from": "ts-admin-user-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'normal' p, count(*) n, round(avg(duration)/1e6,1) ms FROM normal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name='POST /api/v1/adminuserservice/users' UNION ALL SELECT 'abnormal', count(*), round(avg(duration)/1e6,1) FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name='POST /api/v1/adminuserservice/users'",
          "claim": "User-facing POST /api/v1/adminuserservice/users at ts-ui-dashboard rises from about 82 ms to 285 ms; other dashboard endpoints stay flat."
        }
      ]
    }
  ]
}
